function setupGlobalButtonHelpTooltips() {
    if (window.__nexusHelpTooltipsReady) return;
    window.__nexusHelpTooltipsReady = true;

    const tooltip = document.createElement('div');
    tooltip.className = 'nexus-help-tooltip';
    tooltip.style.display = 'none';
    document.body.appendChild(tooltip);

    const cleanupText = (value) => (value || '').replace(/\s+/g, ' ').trim();

    // Describe the actual handler; words in a title are not action identifiers.
    const actionHelp = {
        openAlbumViewer: 'Otvorí obsah albumu na prehliadanie, prehrávanie a výber súborov.',
        discoveryHubShow: 'Otvorí Discovery Hub. Hľadanie spustíš zadaním textu a potvrdením.',
        discoveryHubSearch: 'Vyhľadá albumy podľa zadaného keywordu. Albumy z Balbums zobrazí v poradí Latest.',
        discoveryHubLoadMore: 'Pridá ďalšiu stránku výsledkov aktuálneho vyhľadávania.',
        discoveryHubImport: 'Spustí import tejto položky do Nexus knižnice.',
        discoveryHubImportAll: 'Spustí import všetkých aktuálne zobrazených výsledkov do knižnice.',
        discoveryHubImportSelected: 'Spustí import označených výsledkov do knižnice.',
        discoveryHubRefetchItem: 'Znovu načíta údaje tejto položky zo zdroja.',
        discoveryHubEnrichSelectedAlbums: 'Načíta metadáta označených albumov vrátane dátumov uploadov.',
        discoveryHubFetchMeta: 'Načíta chýbajúce metadáta vybraných alebo všetkých zobrazených položiek.',
        discoveryHubOpenSelectedAlbums: 'Otvorí súbory označených albumov v spoločnom prehľade.',
        discoveryHubResetFilters: 'Zruší filtre výsledkov a obnoví predvolené zobrazenie.',
        albumViewerRefetchOne: 'Načíta chýbajúce trvanie, rozlíšenie a veľkosť tohto videa.',
        albumViewerRefetchMeta: 'Znovu načíta metadáta videí v zvolenom rozsahu.',
        albumViewerFullFetch: 'Načíta údaje všetkých súborov aktuálneho albumu.',
        albumViewerFetchHdThumbs: 'Načíta HD storyboardy; ak chýbajú, vytvorí náhľad zo snímok videa.',
        albumViewerSetHdMode: 'Prepína režim HD náhľadov: 2×2 koláž, 1 snímka alebo vypnuté.',
        albumViewerLoadMore: 'Načíta metadáta ďalších súborov albumu v zvolenom počte.',
        albumViewerPlay: 'Otvorí toto video v prehrávači albumu.',
        albumViewerSelectAll: 'Označí všetky zobrazené súbory, ktoré ešte neboli importované.',
        albumViewerSelectVideosOnly: 'Označí iba zobrazené videá, ktoré ešte neboli importované.',
        albumViewerClear: 'Zruší označenie súborov v albume.',
        albumViewerOpenRelated: 'Vyhľadá súvisiace videá podľa názvu tohto súboru.',
        albumViewerClosePlayer: 'Zatvorí prehrávač albumu.',
        albumViewerPlayerNext: 'Prejde na ďalšie video v aktuálnom výbere albumu.',
        albumViewerImportFromPlayer: 'Importuje aktuálne prehrávané video do knižnice.',
        albumViewerKeepVisibleOnly: 'V dočasnom prehľade ponechá iba súbory vyhovujúce aktuálnym filtrom.',
        combinedHistoryToggle: 'Zobrazí uloženú históriu spoločných albumov a načítaných súborov.',
        showMainGallery: 'Zobrazí hlavnú galériu videí uložených v Nexus knižnici.',
        showTesterVids: 'Zobrazí videá načítané z aktuálneho Eporner mixu.',
        loadVideos: 'Obnoví zoznam videí podľa aktuálnych filtrov galérie.',
        toggleFavorite: 'Prepne označenie videa ako obľúbené.',
        toggleWatched: 'Prepne označenie videa ako pozreté.',
        handleCardClick: 'Otvorí video z tejto karty v prehrávači.',
        openSource: 'Otvorí pôvodnú stránku videa v novej karte.',
        refreshVideo: 'Znovu načíta údaje a odkaz videa zo zdroja.',
        showImportDesk: 'Otvorí prehľad importov a ich priebehu.',
        phOpen: 'Otvorí vyhľadávanie a prehliadanie videí z PornHubu.',
        ephOpen: 'Otvorí spoločné vyhľadávanie videí z Eporner, WhoresHub a PornTrex.',
        showRedGifsBrowser: 'Otvorí prehliadač klipov RedGIFs.',
        showOldGallery: 'Otvorí staršie zobrazenie Nexus galérie.',
        openLogPanel: 'Zobrazí záznamy operácií a chýb aplikácie.',
        loadSmartPlaylist: 'Zobrazí videá vyhovujúce pravidlám tohto playlistu.',
    };
    const inferHelpText = (element) => {
        const title = cleanupText(element.getAttribute('title') || element.dataset.nativeTitle);
        if (title) return title;
        const expression = Array.from(element.attributes || [])
            .filter(a => a.name.startsWith('@click') || a.name.startsWith('x-on:click'))
            .map(a => a.value).join(' ');
        for (const [action, help] of Object.entries(actionHelp)) {
            if (new RegExp('\\b' + action + '\\s*\\(').test(expression)) return help;
        }
        const label = element.cloneNode(true);
        label.querySelectorAll('.material-icons, .material-icons-round, .material-symbols-rounded').forEach(icon => icon.remove());
        // Unknown controls keep their real accessible label; never invent a function.
        return cleanupText(element.getAttribute('aria-label') || label.textContent);
    };

    let activeEl = null;

    const showTooltip = (element, event) => {
        const explicit = cleanupText(element.dataset.help);
        const helpText = explicit || inferHelpText(element);
        if (!helpText) return;

        if (element.hasAttribute('title')) {
            element.dataset.nativeTitle = element.getAttribute('title');
            element.removeAttribute('title');
        }

        tooltip.textContent = helpText;
        tooltip.style.display = 'block';
        activeEl = element;
        moveTooltip(event);
    };

    const hideTooltip = (element) => {
        if (element && element.dataset && element.dataset.nativeTitle && !element.getAttribute('title')) {
            element.setAttribute('title', element.dataset.nativeTitle);
        }
        tooltip.style.display = 'none';
        activeEl = null;
    };

    const moveTooltip = (event) => {
        if (!activeEl || !event) return;
        const margin = 14;
        const width = 360;
        let left = event.clientX + 18;
        let top = event.clientY + 18;

        if (left + width + margin > window.innerWidth) {
            left = window.innerWidth - width - margin;
        }
        if (top + tooltip.offsetHeight + margin > window.innerHeight) {
            top = event.clientY - tooltip.offsetHeight - 14;
        }
        if (top < margin) top = margin;
        if (left < margin) left = margin;

        tooltip.style.left = `${left}px`;
        tooltip.style.top = `${top}px`;
    };

    document.addEventListener('mouseover', (event) => {
        const element = event.target.closest('button, [role="button"], a[href]');
        if (!element) return;
        showTooltip(element, event);
    });

    document.addEventListener('mousemove', (event) => {
        if (!activeEl) return;
        moveTooltip(event);
    });

    document.addEventListener('mouseout', (event) => {
        const element = event.target.closest('button, [role="button"], a[href]');
        if (!element) return;
        hideTooltip(element);
    });
}

