        thumbnailMonitorTime(value) {
            if (value == null) return 'počítam…';
            const seconds = Math.max(0, Math.round(Number(value) || 0));
            return seconds < 60 ? `${seconds} s` : `${Math.floor(seconds / 60)} min ${seconds % 60} s`;
        },

        async pollThumbnailMonitor() {
            if (this._thumbnailMonitorBusy) return;
            this._thumbnailMonitorBusy = true;
            clearTimeout(this._thumbnailMonitorTimer);
            const controller = new AbortController();
            const deadline = setTimeout(() => controller.abort(), 8000);
            try {
                const response = await fetch('/api/v1/maintenance/smart-rethumb/status', {
                    credentials: 'same-origin', cache: 'no-store', signal: controller.signal,
                });
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                const data = await response.json();
                const wasRunning = this.thumbnailMonitor.running;
                this.thumbnailMonitor = { running: !!data.running, progress: data.progress || {},
                    updatedAt: new Date().toLocaleTimeString('sk-SK'), error: '' };
                if (wasRunning && !data.running) {
                    for (const video of this.videos) video._rethumbing = false;
                    await this.loadVideos(true);
                }
            } catch (error) {
                this.thumbnailMonitor.error = 'Stav sa nepodarilo načítať. Skúsim znovu.';
            } finally {
                clearTimeout(deadline);
                this._thumbnailMonitorBusy = false;
                this._thumbnailMonitorTimer = setTimeout(() => this.pollThumbnailMonitor(),
                    this.thumbnailMonitor.running ? 2000 : 10000);
            }
        },

        async stopSmartRethumb() {
            try {
                const response = await fetch('/api/v1/maintenance/smart-rethumb/stop', { method: 'POST', credentials: 'same-origin' });
                const data = await response.json();
                if (!response.ok) throw new Error(data.detail || `HTTP ${response.status}`);
                this.showToast(data.message, 'stop_circle', 'info');
                await this.pollThumbnailMonitor();
            } catch (error) {
                this.showToast(`Zastavenie zlyhalo: ${error.message || error}`, 'error', 'error');
            }
        },

        getThumbnailQuality(video) {
            return video.thumbnail_quality || { status: 'unknown', label: 'NEOVERENÉ', reason: 'Náhľad zatiaľ nebol overený' };
        },
