            const resumeEnrich = !!this.discoveryHubEnrichPaused;
            const resumeLoad = !!this.discoveryHubLoadPaused && this.discoveryHubHasMore;
            this.discoveryHubEnrichPaused = false;
            this.discoveryHubLoadPaused = false;
