        // ── in-hub player ──
        _phDestroyHls() {
            if (this._phHls) { try { this._phHls.destroy(); } catch (_) { } this._phHls = null; }
            const v = this.$refs.phvideo;
            if (v) { try { v.pause(); v.removeAttribute('src'); v.load(); } catch (_) { } }
        },
        // #1 Predictive pre-resolution. Hovering a card for ~400ms warms the
        // server-side stream cache so the eventual click plays instantly.
