        isWhoresHubVideoMatchingFilters(video) {
            const resolution = Number(video?.resolution || 0);
            const duration = Number(video?.duration || 0);
            const uploadType = (video?.upload_type || '').toLowerCase();
            const minQuality = Number(this.whoreshubDiscovery.minQuality || 0);
            const minDuration = Number(this.whoreshubDiscovery.minDuration || 0);
            const desiredUploadType = (this.whoreshubDiscovery.uploadType || 'all').toLowerCase();

            const matchesQuality = resolution >= minQuality;
            const matchesDuration = !minDuration || duration >= minDuration;
            const matchesUploadType = desiredUploadType === 'all' || uploadType === desiredUploadType;

            return matchesQuality && matchesDuration && matchesUploadType;
        },

        getWhoresHubMatchingResults() {
            const results = Array.isArray(this.whoreshubDiscovery.results) ? this.whoreshubDiscovery.results : [];
            return results.filter(video => this.isWhoresHubVideoMatchingFilters(video));
        },

