        async tnaflixScanProfile() {
            const url = this.tnaflixDiscovery.profileUrl.trim();
            if (!url) return;
            this.tnaflixDiscovery.loading = true;
            this.tnaflixDiscovery.results = [];
            this.tnaflixDiscovery.selected = [];
            this.tnaflixDiscovery.profile = null;
            this.tnaflixDiscovery.relatedProfiles = [];
            this.tnaflixDiscovery.statusMsg = 'Načítavam profil...';
            this.tnaflixDiscovery.filter.keyword = '';
            try {
                const params = new URLSearchParams({
                    url,
                    max_pages: this.tnaflixDiscovery.maxPages,
                });
                const resp = await fetch(`/api/v1/discovery/tnaflix/profile?${params}`, {
                    headers: this.getAuthHeaders(),
                });
                const data = await resp.json();
                if (!resp.ok) throw new Error(data.detail || `HTTP ${resp.status}`);
                const cards = (data.cards || []).map(c => ({ ...c, _imported: false }));
                this.tnaflixDiscovery.results = cards;
                this.tnaflixDiscovery.profile = data.profile || { username: data.uploader };
                this.tnaflixDiscovery.relatedProfiles = data.related_profiles || data.profile?.related_profiles || [];
                this.tnaflixDiscovery.statusMsg = cards.length ? `Načítaných ${cards.length} videí` : 'Žiadne videá nenájdené';
                if (cards.length) this.tnaflixCacheSaveProfile();
            } catch (e) {
                this.tnaflixDiscovery.statusMsg = 'Chyba: ' + e.message;
                this.showToast('Tnaflix profil: ' + e.message, 'error', 'error');
            } finally {
                this.tnaflixDiscovery.loading = false;
            }
        },

        tnaflixOpenProfile(profile) {
            const url = typeof profile === 'string' ? profile : (profile?.url || '');
            if (!url) return;
            this.tnaflixDiscovery.profileUrl = url;
            this.tnaflixDiscovery.tab = 'profile';
            this.tnaflixScanProfile();
        },

        async tnaflixFindProfiles() {
            const finder = this.tnaflixDiscovery.profileFinder;
            finder.loading = true;
            finder.profiles = [];
            finder.statusMsg = 'Hľadám profily...';
            try {
                const params = new URLSearchParams({
                    mode: finder.mode || 'last_updated',
                    limit: finder.limit || 50,
                    pages: finder.pages || 3,
                });
                const resp = await fetch(`/api/v1/discovery/tnaflix/profiles?${params}`, {
                    headers: this.getAuthHeaders(),
                });
                const data = await resp.json();
                if (!resp.ok) throw new Error(data.detail || data.error || `HTTP ${resp.status}`);
                finder.profiles = data.profiles || [];
                finder.statusMsg = finder.profiles.length
                    ? `Nájdených ${finder.profiles.length} profilov`
                    : 'Žiadne profily nenájdené';
            } catch (e) {
                finder.statusMsg = 'Chyba: ' + e.message;
                this.showToast('Tnaflix profiles: ' + e.message, 'error', 'error');
            } finally {
                finder.loading = false;
            }
        },

