            const directHlsUrl = video.url && video.url.startsWith('http') ? video.url : null;
            const hasDirectPlayableUrl = ['.m3u8', '.mp4', '.webm', '.m4v', '/stream/', 'xnxx-cdn.com/'].some(token => videoUrlLower.includes(token));
