            if (!src && isCyberFile && video.id) {
                this.showToast('Získavam čerstvý CyberFile stream...', 'hourglass_empty', 'info', 1400);
                try {
                    const cyberRes = await fetch(`/api/v1/stream/cyberfile/${video.id}`);
                    if (cyberRes.ok) {
                        const cyberData = await cyberRes.json();
                        if (cyberData.stream_url) {
                            video.url = String(cyberData.stream_url).trim();
                            // Do not proxy CyberFile's single-use token: the browser
                            // must consume it directly, with no duplicate FFmpeg/proxy hit.
                            src = video.url;
                        }
                    } else {
                        const detail = await cyberRes.json().catch(() => ({}));
                        this.showToast(detail.detail || 'CyberFile stream nie je dostupný', 'warning', 'warning', 4500);
                    }
                } catch (e) {
                    console.warn(`[Player ${playerIdx}] CyberFile JIT failed:`, e);
                    this.showToast('CyberFile stream sa nepodarilo obnoviť', 'warning', 'warning', 4500);
                }
            }

            // --- LULU JIT RESOLUTION ---
            if (isLulu) {
                this.showToast('Extracting fresh Lulu stream...', 'hourglass_empty', 'info', 1000);
                console.log(`[Player ${playerIdx}] LuluStream detected, fetching JIT fresh URL...`);
                try {
                    const luluRes = await fetch(`/api/v1/stream/lulu/${video.id}`);
                    if (luluRes.ok) {
                        const luluData = await luluRes.json();
                        if (luluData.stream_url) {
                            video.url = luluData.stream_url;
                            src = luluData.stream_url;
                            console.log(`[Player ${playerIdx}] LuluStream fresh URL obtained.`);
                        }
                    } else {
                        console.error(`[Player ${playerIdx}] LuluStream JIT failed with status:`, luluRes.status);
                    }
                } catch (e) {
                    console.error(`[Player ${playerIdx}] LuluStream JIT failed:`, e);
                }
            }

